    "abstraction": {},
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "at(6,3)",
          "hasCart",
          "N"
        ]
      }
    }
  },
  {
    "id": "no_walking_without_cart_outside_item_area",
