        "and": [
          "at(6,3)",
          "INTERACT"
        ]
      }
    }
  },
  {
    "id": "set_down_cart_at_6_3",
    "text": "When the shopper interacts at cell (6,3) while holding a cart, they are obliged to become cartless afterward.",
